class Solution {
public:
    std::vector<int> topStudents(std::vector<std::string>& positive_feedback, std::vector<std::string>& negative_feedback, std::vector<std::string>& report, std::vector<int>& student_id, int k) {
        std::unordered_set<std::string> pos(positive_feedback.begin(), positive_feedback.end());
        std::unordered_set<std::string> neg(negative_feedback.begin(), negative_feedback.end());
        int n = report.size();
        std::vector<std::pair<int, int>> scored;
        for (int i = 0; i < n; ++i) {
            int score = 0;
            std::stringstream ss(report[i]);
            std::string word;
            while (ss >> word) {
                if (pos.count(word)) score += 3;
                else if (neg.count(word)) score -= 1;
            }
            scored.push_back({score, student_id[i]});
        }
        std::sort(scored.begin(), scored.end(), [](const auto& a, const auto& b) {
            if (a.first != b.first) return a.first > b.first;
            return a.second < b.second;
        });
        std::vector<int> ans;
        for (int i = 0; i < k; ++i) ans.push_back(scored[i].second);
        return ans;
    }
};

class Solution {
    public java.util.List<Integer> topStudents(String[] positive_feedback, String[] negative_feedback, String[] report, int[] student_id, int k) {
        java.util.Set<String> pos = new java.util.HashSet<>(java.util.Arrays.asList(positive_feedback));
        java.util.Set<String> neg = new java.util.HashSet<>(java.util.Arrays.asList(negative_feedback));
        int n = report.length;
        int[][] scored = new int[n][2];
        for (int i = 0; i < n; i++) {
            int score = 0;
            String[] words = report[i].split(" ");
            for (String w : words) {
                if (pos.contains(w)) score += 3;
                else if (neg.contains(w)) score -= 1;
            }
            scored[i][0] = score;
            scored[i][1] = student_id[i];
        }
        java.util.Arrays.sort(scored, (a, b) -> {
            if (a[0] != b[0]) return Integer.compare(b[0], a[0]);
            return Integer.compare(a[1], b[1]);
        });
        java.util.List<Integer> ans = new java.util.ArrayList<>();
        for (int i = 0; i < k; i++) ans.add(scored[i][1]);
        return ans;
    }
}

var topStudents = function(positive_feedback, negative_feedback, report, student_id, k) {
    const pos = new Set(positive_feedback);
    const neg = new Set(negative_feedback);
    const scored = [];
    for (let i = 0; i < report.length; i++) {
        let score = 0;
        const words = report[i].split(' ');
        for (const w of words) {
            if (pos.has(w)) score += 3;
            else if (neg.has(w)) score -= 1;
        }
        scored.push({ score, id: student_id[i] });
    }
    scored.sort((a, b) => {
        if (a.score !== b.score) return b.score - a.score;
        return a.id - b.id;
    });
    return scored.slice(0, k).map(x => x.id);
};
